package arrays

import "testing"

func changeCopy(values [3]int) {
	values[0] = 99
}

func TestArrayBoundaryAndCopy(t *testing.T) {
	values := [3]int{10, 20, 30}

	last := len(values) - 1
	if got := values[last]; got != 30 {
		t.Fatalf("last value = %d, want 30", got)
	}

	changeCopy(values)
	if values[0] != 10 {
		t.Fatalf("caller changed to %d", values[0])
	}
}

